def choose_move(observation):
    obs = observation or {}
    wx = obs.get('grid_width', 0)
    wy = obs.get('grid_height', 0)
    sp = obs.get('self_position', {})
    op = obs.get('opponent_position', {})
    rs = obs.get('resources', [])
    scr = obs.get('scores', {})
    rem = obs.get('remaining_resource_count', 0)
    apath = obs.get('self_path', [])
    opath = obs.get('opponent_path', [])
    ax = sp.get('x', 0)
    ay = sp.get('y', 0)
    ox = op.get('x', 0)
    oy = op.get('y', 0)

    # Default stay
    best = [0, 0]

    # Simple heuristic: move toward nearest resource if available, else move away from opponent slightly
    if isinstance(rs, list) and rs:
        best_r = None
        bestd = 10**9
        for r in rs:
            rx = r.get('x', 0)
            ry = r.get('y', 0)
            d = abs(rx - ax) + abs(ry - ay)
            if d < bestd:
                bestd = d
                best_r = (rx, ry)
        if best_r is not None:
            rx, ry = best_r
            dx = 0
            dy = 0
            if rx > ax:
                dx = 1
            elif rx < ax:
                dx = -1
            if ry > ay:
                dy = 1
            elif ry < ay:
                dy = -1
            if dx != 0 or dy != 0:
                return [dx, dy]

    # If no resource or not closer, try to move away from opponent
    if ox is not None and oy is not None:
        dx = 0
        dy = 0
        if ax < ox:
            dx = -1
        elif ax > ox:
            dx = 1
        if ay < oy:
            dy = -1
        elif ay > oy:
            dy = 1
        if dx != 0 or dy != 0:
            return [dx, dy]

    # Fallback: attempt to move towards center of grid
    cx, cy = wx // 2, wy // 2
    dx = 0
    dy = 0
    if ax < cx:
        dx = 1
    elif ax > cx:
        dx = -1
    if ay < cy:
        dy = 1
    elif ay > cy:
        dy = -1
    return [dx, dy]
